#include "VisualExtensionSDK.h"
FTJServiceVisualSpec UTJVisualExtensionSDK::CreateServiceVisualSpec(const FString&P){return {P,TEXT("UE5_Nanite_ServiceBuilding"),TEXT("TJSPACE_MasterMaterialSet"),TEXT("1.0.0")};}
FTJCitadelThemeSpec UTJVisualExtensionSDK::CreateCitadelTheme(const FTJServiceVisualSpec&S){FTJCitadelThemeSpec T;T.ThemeId=FString::Printf(TEXT("theme:%s"),*S.PackageId);T.Name=TEXT("TJ Citadel Theme");T.BaseMaterialSet=S.MaterialSet;return T;}
FTJVisualPluginSpec UTJVisualExtensionSDK::CreateVisualPlugin(const FTJServiceVisualSpec&S){FTJVisualPluginSpec P;P.PluginId=FString::Printf(TEXT("visual:%s"),*S.PackageId);P.Version=S.VisualVersion;P.VisualEntryPoint=S.BuildingMesh;return P;}
FTJVisualModManifest UTJVisualExtensionSDK::PackageVisualMod(const FString&D){FTJVisualModManifest M;M.ModId=FString::Printf(TEXT("mod:%s"),*FPaths::GetCleanFilename(D));M.PackageId=FPaths::GetCleanFilename(D);M.Signature=FString::Printf(TEXT("signed:%s"),*M.ModId);M.Assets.Add(D);return M;}
bool UTJVisualExtensionSDK::HotReloadVisual(const FString&P){return !P.IsEmpty();}
FTJComplianceReport UTJVisualExtensionSDK::ValidateVisualCompliance(const FTJVisualModManifest&M){FTJComplianceReport R;R.ModId=M.ModId;R.bCompliant=true;const FString S=M.ModId.ToLower();const TArray<FString> Forbidden={TEXT("pixel"),TEXT("cel"),TEXT("voxel"),TEXT("unlit")};for(const FString&F:Forbidden){if(S.Contains(F)){R.bCompliant=false;R.Errors.Add(FString::Printf(TEXT("Rejected Art Bible violation: %s"),*F));}}if(M.Signature.IsEmpty()){R.bCompliant=false;R.Errors.Add(TEXT("Missing signed visual-mod seal"));}if(M.Assets.Num()==0)R.Warnings.Add(TEXT("No visual assets declared"));return R;}
bool UTJVisualExtensionSDK::RegisterVisualExtensionPoint(const FTJVisualExtensionManifest&M){return !M.ExtensionId.IsEmpty()&&!M.Version.IsEmpty()&&!M.EntryPoint.IsEmpty()&&!M.Signature.IsEmpty();}